from playwright.sync_api import sync_playwright
OUT=pathlib.Path(__file__).resolve().parents[2]/'docs/adventures-v14';(OUT/'screenshots').mkdir(exist_ok=True,parents=True)
result={'checks':[],'environment':'Managed Chromium SwiftShader, phone/tablet emulation and actual CDP touch. Physical devices/controllers unverified.'}
