with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 for device,size in [('phone',{'width':390,'height':844}),('tablet',{'width':1024,'height':768})]:
  c=b.new_context(viewport=size,has_touch=True,is_mobile=True);g=c.new_page();g.set_default_timeout(120000);errors=[];g.on('pageerror',lambda e:errors.append(str(e)));g.goto('http://127.0.0.1:5175/adventures.html?test=1');g.wait_for_function('window.adventure?.ready');g.locator('#enter').tap();g.wait_for_function('!!adventure.game.wildlife');g.evaluate('window.requestAnimationFrame=()=>0;adventure.game.frame=()=>{}');g.wait_for_timeout(150)
  data=g.evaluate('''()=>{const g=adventure.game;window.oldId=g.session.current.id;window.view=(x,z,yaw=0,pitch=.25)=>{Object.assign(g.player,{x,z,y:g.outdoorSpace.ground(x,z)+.002,vy:0,grounded:true});g.velocity.set(0,0);g.actorYaw=yaw+Math.PI;g.update(1/120,{x:0,z:0,run:false});g.actor.rotation.y=g.actorYaw;g.cameraYaw=yaw;g.cameraPitch=pitch;g.cameraPosition.set(0,0,0);g.cameraUpdate(1/60);g.updateContext();g.renderScene();g.worldMap.update(g.mapPose(),performance.now(),true);document.getElementById('toast').hidden=true};return{layout:g.data.layout,height:g.wildlife.height,clip:g.wildlife.clip,textureBefore:g.wildlife.textureBefore,textureAfter:g.wildlife.textureAfter,body:g.landscape.obstacles.filter(o=>o.name==='wildlife-fox').length}}''');check(device+' explicit layout-8 wildlife uses the authored Survey clip, human-relative height and capped texture',data=={'layout':8,'height':.62,'clip':'Survey','textureBefore':1024,'textureAfter':256,'body':1},data)
  g.evaluate('view(-32.5,-14)');g.screenshot(path=str(OUT/'screenshots'/f'foxglade-{device}.png'))
